export type DepartureSlot = {
  date: string
  status: 'available' | 'fast-filling' | 'sold-out'
}

export type Hotel = {
  city: string
  name: string
  stars: number
  nights: number
  roomType: string
  meal: string
}

export type AddOn = {
  id: string
  label: string
  price: number
  note?: string
}

export type ItineraryDay = {
  day: number
  title: string
  description: string
  hotel?: string
  meals: string[]
}

export type Package = {
  id: string
  name: string
  nights: number
  days: number
  region: 'europe' | 'africa' | 'oceania' | 'asia' | 'americas'
  workdriveUrl: string
  img: string
  gallery: string[]
  tag?: string
  basePrice: number
  departures: DepartureSlot[]
  singleSupplement: number
  tripleReduction: number
  addOns: AddOn[]
  hotels: Hotel[]
  travelerTypes: string[]
  themes: string[]
  exCities: string[]
  starRating: number
  hasPrice: boolean
  highlights: string[]
  itinerary: ItineraryDay[]
}

